//! Count the struct fields visible past their module and the lint expects, per file.
//!
//! `adtb-structure ROOT...` prints `ROW PATH COUNT` for each `.rs` file under the roots
//! (skipping `target` directories) with a field declared `pub` (row `pub_fields`) or with a
//! restricted visibility other than `pub(self)` (row `crate_fields`). Named and tuple fields of
//! structs and unions count; fields generated by macros are not parsed and do not count. An
//! attribute naming `clippy::disallowed_methods` counts in row `disallowed_methods`, or in
//! `disallowed_methods_test` when an item, statement or expression on its path carries
//! `#[cfg(test)]` or `#[cfg(all(.., test, ..))]`, or it sits in `#[cfg_attr(test, ..)]`. The lint
//! list is parsed: a `reason` string never counts. Macro bodies are not parsed; each
//! `clippy::disallowed_methods` in their tokens counts. Exits 1 and names the file when one does
//! not parse.

use std::fs;
use std::io::Write;
use std::path::Path;
use std::process::ExitCode;

use syn::buffer::Cursor;
use syn::parse::ParseStream;
use syn::punctuated::Punctuated;
use syn::visit::Visit;
use syn::{Attribute, Field, Macro, Meta, Token, Visibility};

#[derive(Default)]
struct Counts {
    crate_fields: u32,
    pub_fields: u32,
    disallowed_methods: u32,
    disallowed_methods_test: u32,
    in_test: u32,
}

fn metas(list: &syn::MetaList) -> Vec<Meta> {
    list.parse_args_with(Punctuated::<Meta, Token![,]>::parse_terminated)
        .map(|p| p.into_iter().collect())
        .unwrap_or_default()
}

fn cond_is_test(meta: &Meta) -> bool {
    match meta {
        Meta::Path(p) => p.is_ident("test"),
        Meta::List(list) if list.path.is_ident("all") => metas(list).iter().any(cond_is_test),
        _ => false,
    }
}

fn is_cfg_test(attr: &Attribute) -> bool {
    match &attr.meta {
        Meta::List(list) if list.path.is_ident("cfg") => {
            matches!(metas(list).as_slice(), [m] if cond_is_test(m))
        }
        _ => false,
    }
}

fn is_disallowed_methods(meta: &Meta) -> bool {
    let Meta::Path(p) = meta else {
        return false;
    };
    let names: Vec<_> = p.segments.iter().map(|s| s.ident.to_string()).collect();
    names == ["clippy", "disallowed_methods"]
}

fn is_lint_attr(meta: &Meta) -> bool {
    let Meta::List(list) = meta else {
        return false;
    };
    ["expect", "allow", "warn", "deny", "forbid"]
        .iter()
        .any(|l| list.path.is_ident(l))
        && metas(list).iter().any(is_disallowed_methods)
}

fn cursor_matches(mut cur: Cursor) -> u32 {
    let mut n = 0;
    while !cur.eof() {
        if let Some((a, c)) = cur.ident()
            && a == "clippy"
            && let Some((c1, c)) = c.punct()
            && c1.as_char() == ':'
            && let Some((c2, c)) = c.punct()
            && c2.as_char() == ':'
            && let Some((b, _)) = c.ident()
            && b == "disallowed_methods"
        {
            n += 1;
        }
        if let Some((inside, _, _, after)) = cur.any_group() {
            n += cursor_matches(inside);
            cur = after;
        } else if let Some((_, after)) = cur.token_tree() {
            cur = after;
        } else {
            break;
        }
    }
    n
}

fn macro_matches(m: &Macro) -> u32 {
    m.parse_body_with(|input: ParseStream| {
        input.step(|c| {
            let mut end = *c;
            while let Some((_, after)) = end.token_tree() {
                end = after;
            }
            Ok((cursor_matches(*c), end))
        })
    })
    .unwrap_or(0)
}

impl Counts {
    fn record(&mut self, test: bool) {
        if test {
            self.disallowed_methods_test += 1;
        } else {
            self.disallowed_methods += 1;
        }
    }

    fn scoped(&mut self, attrs: &[Attribute], visit: impl FnOnce(&mut Self)) {
        let test = attrs.iter().any(is_cfg_test);
        self.in_test += u32::from(test);
        visit(self);
        self.in_test -= u32::from(test);
    }
}

macro_rules! scoped_visits {
    ($($method:ident, $ty:ident, $walk:ident;)*) => {
        $(
            fn $method(&mut self, i: &'ast syn::$ty) {
                self.scoped(&i.attrs, |c| syn::visit::$walk(c, i));
            }
        )*
    };
}

impl<'ast> Visit<'ast> for Counts {
    fn visit_field(&mut self, field: &'ast Field) {
        match &field.vis {
            Visibility::Public(_) => self.pub_fields += 1,
            Visibility::Restricted(r) if !r.path.is_ident("self") => self.crate_fields += 1,
            _ => {}
        }
        syn::visit::visit_field(self, field);
    }

    fn visit_attribute(&mut self, attr: &'ast Attribute) {
        let in_test = self.in_test > 0;
        if is_lint_attr(&attr.meta) {
            self.record(in_test);
        } else if let Meta::List(list) = &attr.meta
            && list.path.is_ident("cfg_attr")
            && let [cond, rest @ ..] = metas(list).as_slice()
        {
            let test = in_test || cond_is_test(cond);
            for _ in rest.iter().filter(|m| is_lint_attr(m)) {
                self.record(test);
            }
        }
    }

    fn visit_macro(&mut self, m: &'ast Macro) {
        for _ in 0..macro_matches(m) {
            self.record(self.in_test > 0);
        }
        syn::visit::visit_macro(self, m);
    }

    scoped_visits! {
        visit_item_mod, ItemMod, visit_item_mod;
        visit_item_fn, ItemFn, visit_item_fn;
        visit_item_impl, ItemImpl, visit_item_impl;
        visit_item_trait, ItemTrait, visit_item_trait;
        visit_item_struct, ItemStruct, visit_item_struct;
        visit_item_enum, ItemEnum, visit_item_enum;
        visit_item_union, ItemUnion, visit_item_union;
        visit_item_const, ItemConst, visit_item_const;
        visit_item_static, ItemStatic, visit_item_static;
        visit_item_type, ItemType, visit_item_type;
        visit_item_use, ItemUse, visit_item_use;
        visit_item_macro, ItemMacro, visit_item_macro;
        visit_item_foreign_mod, ItemForeignMod, visit_item_foreign_mod;
        visit_impl_item_fn, ImplItemFn, visit_impl_item_fn;
        visit_impl_item_const, ImplItemConst, visit_impl_item_const;
        visit_impl_item_type, ImplItemType, visit_impl_item_type;
        visit_impl_item_macro, ImplItemMacro, visit_impl_item_macro;
        visit_trait_item_fn, TraitItemFn, visit_trait_item_fn;
        visit_trait_item_const, TraitItemConst, visit_trait_item_const;
        visit_trait_item_type, TraitItemType, visit_trait_item_type;
        visit_trait_item_macro, TraitItemMacro, visit_trait_item_macro;
        visit_local, Local, visit_local;
        visit_variant, Variant, visit_variant;
        visit_arm, Arm, visit_arm;
        visit_expr_block, ExprBlock, visit_expr_block;
        visit_expr_unsafe, ExprUnsafe, visit_expr_unsafe;
        visit_expr_closure, ExprClosure, visit_expr_closure;
        visit_expr_call, ExprCall, visit_expr_call;
        visit_expr_method_call, ExprMethodCall, visit_expr_method_call;
        visit_expr_macro, ExprMacro, visit_expr_macro;
        visit_expr_if, ExprIf, visit_expr_if;
        visit_expr_match, ExprMatch, visit_expr_match;
        visit_expr_loop, ExprLoop, visit_expr_loop;
        visit_expr_while, ExprWhile, visit_expr_while;
        visit_expr_for_loop, ExprForLoop, visit_expr_for_loop;
        visit_expr_async, ExprAsync, visit_expr_async;
        visit_expr_const, ExprConst, visit_expr_const;
        visit_expr_struct, ExprStruct, visit_expr_struct;
    }
}

fn rust_files(dir: &Path, found: &mut Vec<String>) -> std::io::Result<()> {
    let mut entries: Vec<_> = fs::read_dir(dir)?.collect::<Result<_, _>>()?;
    entries.sort_by_key(fs::DirEntry::file_name);
    for entry in entries {
        let path = entry.path();
        if entry.file_type()?.is_dir() {
            if entry.file_name() != "target" {
                rust_files(&path, found)?;
            }
        } else if path.extension().is_some_and(|e| e == "rs") {
            found.push(path.to_string_lossy().into_owned());
        }
    }
    Ok(())
}

fn run(roots: &[String]) -> Result<(), String> {
    let mut files = Vec::new();
    for root in roots {
        rust_files(Path::new(root), &mut files).map_err(|e| format!("{root}: {e}"))?;
    }
    for file in files {
        let text = fs::read_to_string(&file).map_err(|e| format!("{file}: {e}"))?;
        let ast = syn::parse_file(&text).map_err(|e| format!("{file}: {e}"))?;
        let mut counts = Counts::default();
        counts.visit_file(&ast);
        let mut out = std::io::stdout().lock();
        for (row, n) in [
            ("crate_fields", counts.crate_fields),
            ("pub_fields", counts.pub_fields),
            ("disallowed_methods", counts.disallowed_methods),
            ("disallowed_methods_test", counts.disallowed_methods_test),
        ] {
            if n > 0 {
                writeln!(out, "{row} {file} {n}").map_err(|e| e.to_string())?;
            }
        }
    }
    Ok(())
}

fn main() -> ExitCode {
    let roots: Vec<String> = std::env::args().skip(1).collect();
    match run(&roots) {
        Ok(()) => ExitCode::SUCCESS,
        Err(message) => {
            writeln!(std::io::stderr(), "adtb-structure: {message}").unwrap_or_default();
            ExitCode::FAILURE
        }
    }
}
